int g_failures = 0;

void check(const std::string& label, const std::string& seen, const std::string& expected) {
  if (seen == expected) return;
  ++g_failures;
  std::cerr << "FAIL: " << label << "\n  seen     " << seen << "\n  expected " << expected << '\n';
}

int free_port() {
  if (const char* pinned = std::getenv("MINERA_TEST_SERVER_PORT"); pinned && *pinned)
    return std::atoi(pinned);
  const int socket_fd = ::socket(AF_INET, SOCK_STREAM, 0);
  sockaddr_in address{};
  address.sin_family = AF_INET;
  address.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
  address.sin_port = 0;
  if (::bind(socket_fd, reinterpret_cast<sockaddr*>(&address), sizeof address) != 0) std::abort();
  socklen_t length = sizeof address;
  ::getsockname(socket_fd, reinterpret_cast<sockaddr*>(&address), &length);
  const int port = ntohs(address.sin_port);
  ::close(socket_fd);
  return port;
}

// A small JSON reader: enough for /api/mine's family results.
struct Json {
  enum class Kind { kNull, kBool, kNumber, kString, kArray, kObject } kind = Kind::kNull;
  std::string text;  // a string's value, a number's or boolean's literal
  std::vector<Json> items;
  std::vector<std::pair<std::string, Json>> members;
  const Json& operator[](const std::string& key) const {
    static const Json null;
    for (const auto& [name, value] : members)
      if (name == key) return value;
    return null;
  }
};

struct JsonReader {
  const std::string& s;
  std::size_t i = 0;
  void space() {
    while (i < s.size() && (s[i] == ' ' || s[i] == '\n' || s[i] == '\r' || s[i] == '\t')) ++i;
  }
  std::string string() {
    std::string out;
    for (++i; i < s.size() && s[i] != '"'; ++i) {
      if (s[i] != '\\') {
        out += s[i];
        continue;
      }
      const char c = s[++i];
      if (c == 'n') out += '\n';
      else if (c == 't') out += '\t';
      else if (c == 'r') out += '\r';
      else if (c == 'b') out += '\b';
      else if (c == 'f') out += '\f';
      else if (c == 'u') {
        const auto code = std::stoul(s.substr(i + 1, 4), nullptr, 16);
        i += 4;
        if (code < 0x80) out += static_cast<char>(code);
        else if (code < 0x800) {
          out += static_cast<char>(0xc0 | (code >> 6));
          out += static_cast<char>(0x80 | (code & 0x3f));
        } else {
          out += static_cast<char>(0xe0 | (code >> 12));
          out += static_cast<char>(0x80 | ((code >> 6) & 0x3f));
          out += static_cast<char>(0x80 | (code & 0x3f));
        }
      } else out += c;
    }
    ++i;
    return out;
  }
  Json value() {
    space();
    Json out;
    if (i >= s.size()) return out;
    const char c = s[i];
    if (c == '{') {
      out.kind = Json::Kind::kObject;
      ++i;
      space();
      if (s[i] == '}') { ++i; return out; }
      while (true) {
        space();
        auto key = string();
        space();
        ++i;  // ':'
        auto item = value();
        out.members.emplace_back(std::move(key), std::move(item));
        space();
        if (s[i++] == '}') return out;
      }
    }
    if (c == '[') {
      out.kind = Json::Kind::kArray;
      ++i;
      space();
      if (s[i] == ']') { ++i; return out; }
      while (true) {
        out.items.push_back(value());
        space();
        if (s[i++] == ']') return out;
      }
    }
    if (c == '"') {
      out.kind = Json::Kind::kString;
      out.text = string();
      return out;
    }
    const auto end = s.find_first_of(",]} \n\r\t", i);
    out.text = s.substr(i, end - i);
    i = end;
    out.kind = out.text == "null" ? Json::Kind::kNull
               : out.text == "true" || out.text == "false" ? Json::Kind::kBool : Json::Kind::kNumber;
    return out;
  }
};

std::string join(std::vector<std::string> parts, const std::string& by) {
  std::sort(parts.begin(), parts.end());
  std::string out;
  for (std::size_t k = 0; k < parts.size(); ++k) out += (k ? by : "") + parts[k];
  return out;
}

std::string sorted_join(std::vector<std::string> parts, const std::string& by) { return join(std::move(parts), by); }

std::string fixed(const Json& value, int digits) {
  char buffer[64];
  std::snprintf(buffer, sizeof buffer, "%.*f", digits, std::strtod(value.text.c_str(), nullptr));
  return buffer;
}

using Fields = std::vector<std::pair<std::string, std::string>>;

std::string plain(const Json& value) {
  if (value.kind == Json::Kind::kNull) return "None";
  std::string out;
  for (const char c : value.text)
    if (c != '\x1f') out += c;
  return out;
}

std::string error_text(const Json& error) {
  if (error.kind == Json::Kind::kString) return error.text;
  const auto& type = error["type"].text;
  return (type.starts_with("builtins.") ? type.substr(9) + ": " : std::string()) + error["message"].text;
}

std::string norm(std::string message) {
  for (bool changed = true; changed;) {
    changed = false;
    for (const char* prefix : {"inductive miner: ", "Heuristics Miner: ", "TypeError: ", "KeyError: ", "ValueError: ",
                               "AttributeError: ", "IndexError: "})
      if (message.starts_with(prefix)) {
        message = message.substr(std::string(prefix).size());
        changed = true;
      }
  }
  return message;
}

std::string fixed_or_nan(const Json& value, int digits) {
  return value.kind == Json::Kind::kNumber && value.text != "NaN" ? fixed(value, digits) : std::string("nan");
}

std::string field_of(const std::string& family) {
  if (family == "alpha") return "alpha_activity_attribute";
  if (family == "inductive") return "inductive_activity_key";
  if (family == "log_skeleton") return "log_skeleton_activity_attribute";
  if (family == "temporal_profile") return "temporal_activity_attribute";
  if (family == "transition_system") return "transition_activity_attribute";
  if (family == "declare") return "declare_activity_attribute";
  return "heuristic_activity_attribute";
}

std::string replay_totals(const Json& replay) {
  std::string totals;
  for (const char* key : {"fitting_traces", "produced", "consumed", "missing", "remaining"})
    totals += (totals.empty() ? "" : "/") + replay[key].text;
  return totals;
}

// One case's outcome in mkhf.py's canonical form (its srv()).
const char* const kDeclareFamilies[] = {"existence", "exactly_one", "init", "responded_existence", "response",
                                        "precedence", "succession", "altresponse", "altprecedence", "altsuccession",
                                        "chainresponse", "chainprecedence", "chainsuccession", "absence", "coexistence",
                                        "noncoexistence", "nonsuccession", "nonchainsuccession"};

std::string outcome(httplib::Client& client, const std::string& name, const std::string& content,
                    const std::string& shape, const std::string& family, const std::string& key) {
  httplib::MultipartFormDataItems items = {{"log", content, name, "application/octet-stream"},
                                           {"include_traces", "false", "", ""},
                                           {field_of(family), key, "", ""}};
  if (family == "hpp") items.push_back({"heuristic_variant", "plusplus", "", ""});
  if (shape != "log") items.push_back({"mining_input_shape", shape, "", ""});
  const auto response = client.Post("/api/mine", items);
  if (!response) return "no response";
  JsonReader reader{response->body};
  const auto body = reader.value();
  if (shape != "log") {
    // Declare alone on the DataFrame shapes: the family's own result.
    const auto& x = body["family_results"]["declare"];
    if (x["executed"].text != "true") return "error: " + norm(error_text(x["error"]));
    std::vector<std::string> shown;
    for (const char* family_name : kDeclareFamilies) {
      std::vector<std::string> rules;
      for (const auto& y : x["result"]["model"]["rules"][family_name].items)
        rules.push_back((y["binary"].text == "true" ? plain(y["first"]) + ">" + plain(y["second"]) : plain(y["first"])) +
                        ":" + y["support"].text + "/" + y["confidence"].text);
      if (!rules.empty()) shown.push_back(std::string(family_name) + "{" + sorted_join(rules, ",") + "}");
    }
    return sorted_join(shown, " ");
  }
  if (body["error"].kind != Json::Kind::kNull) return "error: " + norm(error_text(body["error"]));
  std::vector<std::string> names;
  for (const auto& activity : body["activities"].items) names.push_back(plain(activity["name"]));
  const auto nm = [&](const Json& at, const std::string& null) {
    if (at.kind == Json::Kind::kNull) return null;
    const auto i = std::stoul(at.text);
    return i < names.size() ? names[i] : "#" + at.text;
  };
  if (family == "alpha") {
    const auto& net = body["petri_net"];
    const auto places = std::stoul(net["place_count"].text);
    std::vector<std::vector<std::string>> ins(places), outs(places);
    std::vector<std::string> labels;
    for (const auto& t : net["transitions"].items) {
      const auto label = nm(t["activity"], "None");
      labels.push_back(label);
      for (const auto& p : t["inputs"].items) outs[std::stoul(p.text)].push_back(label);
      for (const auto& p : t["outputs"].items) ins[std::stoul(p.text)].push_back(label);
    }
    std::vector<std::string> shown;
    for (std::size_t p = 0; p < places; ++p)
      shown.push_back(sorted_join(ins[p], ",") + ">" + sorted_join(outs[p], ",") +
                      (net["source"].text == std::to_string(p) ? "#s" : "") +
                      (net["sink"].text == std::to_string(p) ? "#k" : ""));
    return "T[" + sorted_join(labels, ",") + "] P[" + sorted_join(shown, " ") + "] R " +
           replay_totals(body["conformance"]["alpha"]["token_replay"]);
  }
  if (family == "inductive") {
    const std::map<std::string, std::string> ops = {{"sequence", "->"}, {"xor", "X"}, {"exclusive", "X"},
                                                    {"parallel", "+"}, {"loop", "*"}, {"or", "O"}};
    std::function<std::string(const Json&)> walk = [&](const Json& node) -> std::string {
      const auto& op = node["operator"].text;
      if (op == "activity") return nm(node["activity"], "None");
      if (op == "tau" || op == "silent") return "tau";
      const auto found = ops.find(op);
      std::string out = (found == ops.end() ? op : found->second) + "(";
      for (std::size_t k = 0; k < node["children"].items.size(); ++k)
        out += (k ? "," : "") + walk(node["children"].items[k]);
      return out + ")";
    };
    return walk(body["process_tree"]);
  }
  if (family == "log_skeleton") {
    const auto& model = body["log_skeleton"];
    std::string out = "LS";
    for (const char* relation : {"equivalence", "always_after", "always_before", "never_together", "directly_follows"}) {
      std::vector<std::string> pairs;
      for (const auto& p : model[relation].items) pairs.push_back(nm(p["source"], "None") + ">" + nm(p["target"], "None"));
      out += std::string(" ") + relation + "[" + sorted_join(pairs, ",") + "]";
    }
    std::vector<std::string> freq;
    for (const auto& [activity, counts] : model["activ_freq"].members) {
      std::vector<std::string> numbers;
      for (const auto& n : counts.items) numbers.push_back(n.text);
      Json at;
      at.kind = Json::Kind::kNumber;
      at.text = activity;
      freq.push_back(nm(at, "None") + "=" + sorted_join(numbers, "/"));
    }
    return out + " activ_freq[" + sorted_join(freq, ",") + "]";
  }
  if (family == "temporal_profile") {
    std::vector<std::string> entries;
    for (const auto& e : body["temporal_profile"].items)
      entries.push_back(nm(e["source"], "None") + ">" + nm(e["target"], "None") + ":" +
                        fixed_or_nan(e["mean_seconds"], 4) + "/" + fixed_or_nan(e["standard_deviation_seconds"], 4));
    return sorted_join(entries, ";");
  }
  if (family == "transition_system") {
    const auto& system = body["transition_system"];
    std::map<std::string, std::string> state_name;
    std::vector<std::string> states, transitions;
    for (const auto& s : system["states"].items) {
      std::string shown = "(";
      for (std::size_t k = 0; k < s["name_order"].items.size(); ++k)
        shown += (k ? "," : "") + nm(s["name_order"].items[k], "nan");
      shown += ")";
      state_name[s["id"].text] = shown;
      if (s["in_root"].text == "true") states.push_back(shown);
    }
    for (const auto& x : system["transitions"].items)
      transitions.push_back(state_name[x["source"].text] + ">" + state_name[x["target"].text] + ":" +
                            nm(x["activity"], "nan"));
    return "S[" + sorted_join(states, " ") + "] X[" + sorted_join(transitions, " ") + "]";
  }
  if (family == "declare") {
    std::vector<std::string> shown;
    for (const char* family_name : kDeclareFamilies) {
      std::vector<std::string> rules;
      for (const auto& x : body["declare"][family_name].items) {
        const bool binary = std::any_of(x.members.begin(), x.members.end(),
                                        [](const auto& member) { return member.first == "source"; });
        rules.push_back((binary ? nm(x["source"], "None") + ">" + nm(x["target"], "None") : nm(x["activity"], "None")) +
                        ":" + x["support"].text + "/" + x["confidence"].text);
      }
      if (!rules.empty()) shown.push_back(std::string(family_name) + "{" + sorted_join(rules, ",") + "}");
    }
    return sorted_join(shown, " ");
  }
  const auto& net = body["heuristics_net"];
  std::vector<std::string> activities, edges;
  for (const auto& a : net["activities"].items) activities.push_back(plain(a));
  for (const auto& e : net["edges"].items)
    edges.push_back(activities[std::stoul(e["source"].text)] + ">" + activities[std::stoul(e["target"].text)] + ":" +
                    fixed_or_nan(e["dependency"], 6) + "/" + e["frequency"].text);
  return "A[" + sorted_join(activities, ",") + "] E[" + sorted_join(edges, " ") + "] R " +
         replay_totals(body["conformance"]["heuristic"]["token_replay"]);
}

